parameters.jsCode:
// Category name -> Gmail label ID
const LABELS = {
  security:        'Label_7',
  bills:           'Label_6',
  orders:          'Label_13',
  newsletter:      'Label_8',
  general:         'Label_9',
  job_application: 'Label_3',
  job_rejected:    'Label_4',
  job_alert:       'Label_5',
  job_interview:   'Label_12',
};

// Confidence cut-off
const FLOOR = 0.6;

// Runs once per email. $json = Ollama's reply for this one.
// Get the email back. HTTP Request kept only the reply.
// .item follows n8n's link, so failed siblings can't shift it.
const mail = $('When Executed by Another Workflow').item.json;

// Pull the two fields out. ?. and ?? stop a broken reply crashing it.
const { choice, confidence = 0 } = $json.answers?.category ?? {};

// Below the floor, fall back to what this sender has always been
const hinted = mail.senderHint?.match(/were (\w+)\./)?.[1];
const category = confidence >= FLOOR ? choice : (hinted ?? 'other');

return {
  json: {
    ...mail, // id, threadId, Subject, From, body
    category,
    labelId: LABELS[category] ?? '',  // 'other' -> '' -> sorted only
    confidence,                       // for tuning
  },
};

